create table public.teacher_assignments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete restrict, teacher_id uuid not null references public.teachers(id) on delete restrict, subject_id uuid not null references public.subjects(id) on delete restrict, classroom_id uuid not null references public.classrooms(id) on delete restrict, academic_year_id uuid not null references public.academic_years(id) on delete restrict, semester_id uuid not null references public.semesters(id) on delete restrict, is_active boolean not null default true, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(tenant_id,teacher_id,subject_id,classroom_id,semester_id));
create index teacher_assignments_tenant_idx on public.teacher_assignments(tenant_id); alter table public.teacher_assignments enable row level security; revoke all on public.teacher_assignments from anon,authenticated; create policy teacher_assignments_select_tenant on public.teacher_assignments for select to authenticated using(tenant_id=public.current_tenant_id());
insert into public.permissions(code,name,description) values ('teacher_assignments.read','Read teacher assignments','View teacher assignments'),('teacher_assignments.create','Create teacher assignments','Assign teachers'),('teacher_assignments.update','Update teacher assignments','Maintain teacher assignments'),('teacher_assignments.delete','Delete teacher assignments','Remove teacher assignments') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in ('OWNER','PRINCIPAL','STAFF') and p.code like 'teacher_assignments.%' on conflict do nothing;
